@Override
public boolean isFull() {
    return this.building.getAllAssignedCitizen().size() >= this.getModuleMax();
}

@Override
public void onColonyTick(@NotNull IColony colony) {
    if (random.nextInt(this.building.getModulesByType(GuardBuildingModule.class).size()) == 0) {
        return;
    }
    boolean hiredFromTraining = false;
    if (this.building.getSetting(AbstractBuildingGuards.HIRE_TRAINEE).getValue().booleanValue() && !this.isFull() && BuildingUtils.canAutoHire(this.building, this.getHiringMode(), this.getJobEntry())) {
        ICitizenData trainingCitizen = null;
        int maxSkill = 0;
        for (ICitizenData trainee : colony.getCitizenManager().getCitizens()) {
            if (trainee.getJob() == null || (!this.getJobEntry().equals(ModJobs.archer.get()) || !trainee.getJob().getJobRegistryEntry().equals(ModJobs.archerInTraining.get())) && (!this.getJobEntry().equals(ModJobs.knight.get()) || !trainee.getJob().getJobRegistryEntry().equals(ModJobs.knightInTraining.get())) || trainee.getCitizenSkillHandler().getLevel(this.getPrimarySkill()) <= maxSkill) continue;
            maxSkill = trainee.getCitizenSkillHandler().getLevel(this.getPrimarySkill());
            trainingCitizen = trainee;
        }
        if (trainingCitizen != null) {
            hiredFromTraining = true;
            trainingCitizen.setJob(null);
            this.assignCitizen(trainingCitizen);
        }
    }
    if (!hiredFromTraining) {
        super.onColonyTick(colony);
    }
}

