    Network.getNetwork().sendToServer(new CourierHiringModeMessage(this.buildingView, hiringMode, this.getProducer().getRuntimeID()));
}

@Override
public boolean canAssign(ICitizenDataView data) {
    for (IBuildingView bView : this.buildingView.getColony().getClientBuildingManager().getBuildings().values()) {
        CourierAssignmentModuleView view = bView.getModuleViewMatching(CourierAssignmentModuleView.class, m -> !m.buildingView.getId().equals(this.buildingView.getId()));
        if (view == null || !view.getAssignedCitizens().contains(data.getId())) continue;
        return false;
    }
    return !data.isChild() && data.getJobView() != null && data.getJobView().getEntry() == ModJobs.delivery.get();
}

@Override
public int getMaxInhabitants() {
    return this.buildingView.getBuildingLevel() * 2;
}

