import com.minecolonies.api.colony.requestsystem.token.IToken;
import com.minecolonies.core.colony.buildings.moduleviews.RequestTaskModuleView;
import com.minecolonies.core.colony.buildings.moduleviews.WorkerBuildingModuleView;
import com.minecolonies.core.colony.jobs.views.DmanJobView;
import java.util.ArrayList;
import java.util.List;

public class CourierRequestTaskModuleView
extends RequestTaskModuleView {
    @Override
    public List<IToken<?>> getTasks() {
        ArrayList tasks = new ArrayList();
        for (WorkerBuildingModuleView moduleView : this.buildingView.getModuleViews(WorkerBuildingModuleView.class)) {
            for (int citizenId : moduleView.getAssignedCitizens()) {
                ICitizenDataView citizen = this.buildingView.getColony().getCitizen(citizenId);
                if (citizen == null || !(citizen.getJobView() instanceof DmanJobView)) continue;
                tasks.addAll(((DmanJobView)citizen.getJobView()).getDataStore().getQueue());
            }
        }
        return tasks;
    }
}

